import{_ as s,o as i,c as a,ae as t}from"./chunks/framework.Dn7Y7LSn.js";const k=JSON.parse('{"title":"Episode 1-5: Web Primer","description":"","frontmatter":{},"headers":[],"relativePath":"module-3/web-primer.md","filePath":"module-3/web-primer.md"}'),r={name:"module-3/web-primer.md"};function n(o,e,l,p,h,d){return i(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="episode-1-5-web-primer" tabindex="-1">Episode 1-5: Web Primer <a class="header-anchor" href="#episode-1-5-web-primer" aria-label="Permalink to &quot;Episode 1-5: Web Primer&quot;">​</a></h1><h2 id="the-internet-and-the-web" tabindex="-1">The Internet and The Web <a class="header-anchor" href="#the-internet-and-the-web" aria-label="Permalink to &quot;The Internet and The Web&quot;">​</a></h2><p>কম্পিউটার আবিষ্কারের শুরুর দিকে একটি কম্পিউটার নিজে নিজেই কাজ করত। এরপর প্রয়োজন দেখা দেয় একাধিক কম্পিউটারের মধ্যে তথ্য আদান-প্রদান করার। এভাবে অনেকগুলো কম্পিউটার তার দিয়ে বা ওয়্যারলেস মাধ্যমে একে অপরের সাথে কানেক্টেড হয়ে তৈরি করে নেটওয়ার্কিংয়ের। পুরো পৃথিবীর এরকম অসংখ্য নেটওয়ার্ক একত্রে সংযুক্ত (Interconnected) হয়েই তৈরি হয়েছে <strong>Internet</strong>। আমরা সাধারণত কোনো না কোনো ISP (Internet Service Provider) এর মাধ্যমে ইন্টারনেট কানেক্টেড থাকি।</p><p>ইন্টারনেটের উপর ভিত্তি করে গড়ে ওঠা একটি সার্ভিস বা অ্যাপ্লিকেশন হলো <strong>Web Service</strong> (যেমন- ওয়েবসাইট)। এছাড়া ইন্টারনেটের আরো সার্ভিসের মধ্যে রয়েছে ইমেইল, IRC (Internet Relay Chat) ইত্যাদি। অর্থাৎ, এগুলো ইন্টারনেট নয়, বরং ইন্টারনেটের উপর ভিত্তি করে তৈরি এক একটি সার্ভিস।</p><p>ডোমেইন নেম (যেমন <code>www.google.com</code>) দিয়ে ইন্টারনেটে কোনো ওয়েবসাইট ভিজিট করলে, সেই নামের আড়ালে থাকা নির্দিষ্ট সার্ভারের আইপি (IP address) বের করে দেয় <strong>DNS (Domain Name Server)</strong>।</p><h2 id="client-server-architecture" tabindex="-1">Client Server Architecture <a class="header-anchor" href="#client-server-architecture" aria-label="Permalink to &quot;Client Server Architecture&quot;">​</a></h2><p>নেটওয়ার্কের এমন একটি ডিভাইস যার কাছে কোনো রিকোয়েস্ট (Request) পাঠালে, সে সেটি বুঝে কাঙ্ক্ষিত রেসপন্স (Response) ব্যাক করে, তাকেই সার্ভার (Server) বলা হয়। এটি মূলত ক্লায়েন্ট ও সার্ভারের কমিউনিকেশন মডেল।</p><h3 id="_3-tier-architecture" tabindex="-1">3-Tier Architecture <a class="header-anchor" href="#_3-tier-architecture" aria-label="Permalink to &quot;3-Tier Architecture&quot;">​</a></h3><p>ক্লায়েন্ট-সার্ভার আর্কিটেকচারের একটি পরিচিত রূপ হলো 3-Tier Architecture, যার ৩টি প্রধান অংশ থাকে:</p><ol><li><strong>Presentation Layer (Client Part):</strong> ইউজার ইন্টারফেস। (যেমন: Browser, Mobile App)</li><li><strong>Business/Logic Layer (Server Part):</strong> সার্ভার সাইডে রিকোয়েস্ট প্রসেস হয়। (যেমন: PHP অ্যাপ্লিকেশন)</li><li><strong>Data Storage (Database Part):</strong> ডেটা সেভ করে রাখা হয়। (যেমন: MySQL/Relational DB)</li></ol><p>বড় সিস্টেমে অনেক সার্ভার বা ডাটাবেজ থাকতে পারে। এর উপর ভিত্তি করে আরো অনেক লেয়ার বা n-Tier আর্কিটেকচার তৈরি হয়।</p><p><strong>Peer to Peer (P2P) Model:</strong> ক্লায়েন্ট সার্ভারের বাইরেও এই মডেল আছে, যেখানে প্রত্যেকটি ডিভাইস নিজেই ক্লায়েন্ট, নিজেই সার্ভার হিসেবে কাজ করে (যেমন: ব্লকচেইন, টরেন্ট)।</p><h2 id="components-of-a-web-application" tabindex="-1">Components of a Web Application <a class="header-anchor" href="#components-of-a-web-application" aria-label="Permalink to &quot;Components of a Web Application&quot;">​</a></h2><p>একটি ওয়েবসাইটের মূলত দুটি সাইড থাকে-</p><ol><li><strong>Frontend (Client-side):</strong> এতে থাকে HTML (স্ট্রাকচার), CSS (স্টাইল) এবং JS (ইন্টার্যাকশন বা ব্রাউজার সাইড লজিক)।</li><li><strong>Backend (Server-side):</strong><ul><li><strong>Web Server:</strong> (যেমন- Apache, Nginx) এটি মূলত HTTP রিকোয়েস্ট এবং স্ট্যাটিক ফাইল হ্যান্ডেল করে।</li><li><strong>Application Server:</strong> (যেমন- PHP/Laravel, Node.js) ডাইনামিক রিকোয়েস্ট বা বিজনেস লজিক হ্যান্ডেল করে।</li><li><strong>Database Server:</strong> ডেটা সংরক্ষণের জন্য।</li><li><strong>Cache Server:</strong> ডাটাবেজ থেকে বারবার ডেটা রিড করার পরিবর্তে ফাস্ট রেসপন্স করতে।</li></ul></li></ol><h2 id="http-basics" tabindex="-1">HTTP Basics <a class="header-anchor" href="#http-basics" aria-label="Permalink to &quot;HTTP Basics&quot;">​</a></h2><p><strong>HTTP</strong> এর পূর্ণরূপ Hyper Text Transfer Protocol। প্রটোকল হলো এমন কিছু রুল বা গাইডলাইন, যার উপর ভিত্তি করে দুইটি ডিভাইস (যেমন ক্লায়েন্ট ও সার্ভার) নিজেদের মধ্যে কমিউনিকেশন করে এবং ডেটার ফরম্যাট কী হবে তা ডিসাইড করে।</p><h3 id="http-request-format" tabindex="-1">HTTP Request Format <a class="header-anchor" href="#http-request-format" aria-label="Permalink to &quot;HTTP Request Format&quot;">​</a></h3><p>ক্লায়েন্টের পাঠানো রিকোয়েস্ট একটি নির্দিষ্ট ফরম্যাটে থাকে-</p><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /books </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">HTTP</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.1</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Host</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> developer.mozilla.org</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Accept-Language</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fr</span></span></code></pre></div><p>এখানে প্রথম লাইনে থাকে Method (GET), Path (/books), এবং Protocol Version (HTTP/1.1)। নিচের দিকে থাকে রিকোয়েস্ট হেডার্স (Headers)।</p><p><strong>Common HTTP Methods:</strong></p><ul><li><code>GET</code>: ডাটা রিড বা অ্যাক্সেস করা।</li><li><code>POST</code>: নতুন রিসোর্স বা ডেটা তৈরি করা।</li><li><code>PUT / PATCH</code>: পুরাতন রিসোর্স মডিফাই বা আপডেট করা।</li><li><code>DELETE</code>: কোনো রিসোর্স ডিলিট করা।</li></ul><h3 id="http-response-format" tabindex="-1">HTTP Response Format <a class="header-anchor" href="#http-response-format" aria-label="Permalink to &quot;HTTP Response Format&quot;">​</a></h3><p>সার্ভার রিকোয়েস্ট পাওয়ার পর একটি নির্দিষ্ট ফরম্যাটে রেসপন্স দেয়:</p><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">HTTP</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 200</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> OK</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Date</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Sat, 09 Oct 2010 14:28:02 GMT</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Server</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Apache</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Content-Type</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> text/html</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(Response Body content here...)</span></span></code></pre></div><p>এখানে প্রথম লাইনে থাকে Status Code (200) এবং Status Message (OK)।</p><p><strong>HTTP Status Codes:</strong></p><ul><li><code>2xx</code>: Success (200 OK, 201 Created)।</li><li><code>3xx</code>: Redirection (301 Moved Permanently)।</li><li><code>4xx</code>: Client Error (404 Not Found, 403 Forbidden)। রিকোয়েস্টের ফরম্যাট বা ডেটাতে ভুল থাকলে।</li><li><code>5xx</code>: Server Error (500 Internal Server Error, 502 Bad Gateway)। সার্ভারের সাইডে কোনো এরর (Error) হলে।</li></ul><h2 id="cookie-and-session" tabindex="-1">Cookie and Session <a class="header-anchor" href="#cookie-and-session" aria-label="Permalink to &quot;Cookie and Session&quot;">​</a></h2><p>HTTP প্রটোকল হলো <strong>Stateless</strong>। এর মানে হলো, প্রতিবার রিকোয়েস্ট পাঠানোর পর সার্ভার যখন রেসপন্স দেয়, তখন সে পূর্বের কোনো স্টেট (State) বা ইনফরমেশন মনে রাখে না।</p><p>কিন্তু লগইন সিস্টেম বা ইউজারের স্টেট ম্যানেজমেন্টের ক্ষেত্রে এটা মনে রাখা প্রয়োজন। এজন্য <strong>Session</strong> ব্যবহার করা হয়।</p><ol><li>ইউজার লগইন করলে সার্ভার একটি ইউনিক <code>SESSION ID</code> জেনারেট করে এবং সেটি ডেটাবেজ বা ফাইলে ইউজার ইনফরমেশনের সাথে সেভ করে রাখে।</li><li>এরপর রেসপন্সের সাথে ঐ <code>SESSION_ID</code>-টি ক্লায়েন্ট বা ব্রাউজারকে পাঠিয়ে দেয়।</li><li>ব্রাউজার এই আইডিটিকে তার <strong>Cookie</strong>-তে স্টোর করে।</li><li>এরপর ব্রাউজার প্রতিবার রিকোয়েস্ট করার সময় কুকি থেকে ঐ সেশন আইডিটি সাথে পাঠিয়ে দেয়।</li><li>সার্ভার সেটি ম্যাচ করে নির্দিষ্ট ইউজারকে সনাক্ত করে রেসপন্স জেনারেট করে।</li></ol><p>কুকির একটি এক্সপায়রেশন (Expiration) ডেট থাকে, ঐ সময় পার হলে কুকি ডিলিট হয়ে যায়। &quot;Remember me&quot; অপশন ক্লিক করলে কুকির এক্সপায়রেশন বাড়িয়ে দেওয়া হয়।</p>`,34)])])}const g=s(r,[["render",n]]);export{k as __pageData,g as default};
